ession->selected_count) }}</dd></div><div><dt class="text-zinc-500">Unreadable</dt><dd class="font-semibold text-amber-300">{{ number_format($preflight['invalid_count']??$session->failed_count) }}</dd></div><div><dt class="text-zinc-500">Duplicates</dt><dd class="font-semibold text-white">{{ number_format($preflight['duplicate_files']??0) }}</dd></div><div><dt class="text-zinc-500">Ignored safely</dt><dd class="font-semibold text-white">{{ number_format($preflight['ignored_count']??0) }}</dd></div><div><dt class="text-zinc-500">Capacity plan</dt><dd class="font-semibold text-white">{{ number_format(($preflight['estimated_total_bytes']??$session->total_bytes)/1073741824,1) }} GiB</dd></div></dl><div class="mt-4 grid gap-3 rounded-lg border border-zinc-800 bg-zinc-900/70 p-4 text-xs sm:grid-cols-3"><p><span class="text-zinc-500">Orientation flags</span><br><strong class="text-white">{{ number_format($preflight['orientation_tagged_count']??0) }}</strong></p><p><span class="text-zinc-500">Capture dates found</span><br><strong class="text-white">{{ number_format($preflight['captured_at_count']??0) }}</strong></p><p><span class="text-zinc-500">Privacy boundary</span><br><strong class="text-emerald-300">No source paths persisted</strong></p></div></article>@empty<p class="rounded-xl border border-dashed border-zinc-700 p-5 text-zinc-400">No high-volume batch has been inventoried.</p>@endforelse</div></section>
